    const cap = s => s.charAt(0).toUpperCase() + s.slice(1);

    const face = k => {
      const s = SHAPES[k].fs, y = SHAPES[k].fy, e = 9 * s;
      const eye = x => '<circle cx="' + r2(x) + '" cy="' + r2(y - 4 * s) + '" r="' + r2(4.6 * s) + '" fill="#3b2f5c"/>' +
        '<circle cx="' + r2(x + 1.4 * s) + '" cy="' + r2(y - 5.6 * s) + '" r="' + r2(1.6 * s) + '" fill="#fff"/>';
      return eye(50 - e) + eye(50 + e) +
        '<path d="M' + r2(50 - 8 * s) + " " + r2(y + 5 * s) + "Q50 " + r2(y + 12 * s) + " " + r2(50 + 8 * s) + " " + r2(y + 5 * s) +
        '" fill="none" stroke="#3b2f5c" stroke-width="' + r2(3.2 * s) + '" stroke-linecap="round"/>';
    };
