      '<path d="' + SHAPES[k].d + '" fill="' + col[1] + '" stroke="' + col[2] + '" stroke-width="4" stroke-linejoin="round"/>' + face(k) + "</svg>";

    // 8 targets: little sees all five shapes, then three again (never twice in a row); big first matches
    // outlines with different shapes, then its last NAMED rounds ask by name only for shapes it already met
    // (age 5: 2 such rounds, 6-7: 3), never the one just before
    const NAMED = big ? (api.age >= 6 ? 3 : 2) : 0;
    let seq;
    if (big) {
      seq = api.pick(POOL, ROUNDS - NAMED);
      const again = api.pick(seq, NAMED);
      if (again[0] === seq[seq.length - 1]) { const t = again[0]; again[0] = again[1]; again[1] = t; }
      seq = seq.concat(again);
    } else {
      seq = api.shuffle(POOL).concat(api.shuffle(POOL));
      if (seq[4] === seq[5]) { const t = seq[5]; seq[5] = seq[6]; seq[6] = t; }
      seq = seq.slice(0, ROUNDS);
    }

    /* ---- DOM ---- */
    const root = api.el("div", "g-shapes" + (RM ? " shapes-rm" : ""));
    const top = api.el("div", "shapes-top");
    const say = api.el("button", "shapes-say", "🔊");
    say.setAttribute("aria-label", "Say it again");
    const prompt = api.el("div", "shapes-prompt");
    prompt.setAttribute("aria-live", "polite");
    top.appendChild(say);
    top.appendChild(prompt);
    const body = api.el("div", "shapes-body");
    const board = api.el("div", "shapes-board");
    board.setAttribute("role", "img");
    const choices = api.el("div", "shapes-choices");
    choices.setAttribute("role", "group");
    choices.setAttribute("aria-label", "Shapes");
    choices.tabIndex = -1;                        // holds keyboard focus while a right shape's tile is emptied
