      // one pill width for every message: wide enough for the longest one (or the body), never wider than the screen
      const need = Math.ceil((out ? P * 0.68 : P * 0.6 + sb) + longest(Math.min(P * 0.52, 48)) + 2);
      const st = root.style;
      st.setProperty("--pad", pad + "px");
      st.setProperty("--gap", gap + "px");
      st.setProperty("--p", P + "px");
      st.setProperty("--sb", sb + "px");
      st.setProperty("--hole", h + "px");
      st.setProperty("--cs", c + "px");
      st.setProperty("--cw", cw + "px");
