        if (named && !hinted) { hinted = true; showOutline(); }
        const tok = ++msgTok;
        setPrompt("Try again! 🙂", "shapes-oops");
        talk("That's " + art(k) + ". Find the " + target + "!");
        api.timeout(() => { if (tok === msgTok && !busy && !finished) setPrompt("Find the " + target + "!"); }, 1800);
