      if (RM) { land(b, k, col); return; }    // reduced motion: it simply appears in the hole
      const fr = b.querySelector("svg").getBoundingClientRect();
      const tl = br.left + br.width * 0.09, tt = br.top + br.height * 0.09, tw = br.width * 0.82;
      const fl = api.el("div", "shapes-fly", shapeSvg(k, col));
