    // word + a clear picture clue; every word double-checked for spelling. Every picture is an emoji
    // from 2017 or earlier, so hand-me-down tablets show it (no 🪐 or 🦜: those are empty boxes there)
    const SHORT = [["TIGER", "🐯"], ["PIZZA", "🍕"], ["ROBOT", "🤖"], ["PANDA", "🐼"], ["APPLE", "🍎"], ["LEMON", "🍋"],
      ["ZEBRA", "🦓"], ["KOALA", "🐨"], ["TRAIN", "🚂"], ["HORSE", "🐴"], ["FROG", "🐸"], ["LION", "🦁"],
      ["CAKE", "🎂"], ["MOON", "🌙"], ["DRUM", "🥁"]];
    const MEDIUM = [["COOKIE", "🍪"], ["ROCKET", "🚀"], ["GUITAR", "🎸"], ["CAMERA", "📷"], ["PENCIL", "✏️"],
      ["CASTLE", "🏰"], ["TURTLE", "🐢"], ["ORANGE", "🍊"], ["RABBIT", "🐰"], ["CACTUS", "🌵"], ["BANANA", "🍌"],
      ["CARROT", "🥕"], ["MONKEY", "🐒"]];
    const LONG = [["DOLPHIN", "🐬"], ["PENGUIN", "🐧"], ["RAINBOW", "🌈"], ["GIRAFFE", "🦒"], ["BALLOON", "🎈"],
      ["OCTOPUS", "🐙"], ["CHICKEN", "🐔"], ["TRACTOR", "🚜"], ["BICYCLE", "🚲"]];
    // real words hiding in the same letters: the deal never shows them. A child who builds a well-known
    // one is told so, kindly; an odd one (QUIET: LOIN, MONO) just gets the plain "Try again"
